// Generated by OrchestKit Claude Plugin
// Created: 2026-09-14

// Regression: POST https://orchestkit.yonyon.ai/mcp returned 404.
//
// next.config.mjs rewrites /mcp to /api/mcp, but middleware runs BEFORE
// rewrites. /mcp was missing from SERVED_EXACT, so shouldJsonError() answered
// every non-browser request with a structured 404 and fired agent:not-found,
// and the rewrite never ran. These tests call the REAL middleware.
import { NextRequest } from "next/server";
import { beforeEach, describe, expect, it, vi } from "vitest";

const reportServerEvent = vi.fn();
vi.mock("@/lib/analytics-server", () => ({
	reportServerEvent: (...args: unknown[]) => reportServerEvent(...args),
	reportServerEvents: vi.fn(),
}));

import { middleware } from "@/middleware";

/** An MCP Streamable HTTP client request, as Claude Code or an SDK sends it. */
function mcpRequest(path: string, method = "POST") {
	return new NextRequest(`https://orchestkit.yonyon.ai${path}`, {
		method,
		headers: {
			accept: "application/json, text/event-stream",
			"content-type": "application/json",
			"user-agent": "node",
		},
		body:
			method === "POST"
				? JSON.stringify({ jsonrpc: "2.0", id: 1, method: "tools/list" })
				: undefined,
	});
}

function eventNames() {
	return reportServerEvent.mock.calls.map((c) => c[1]);
}

describe("middleware lets the bare /mcp endpoint reach its rewrite", () => {
	beforeEach(() => reportServerEvent.mockClear());

	for (const method of ["POST", "GET"]) {
		it(`${method} /mcp passes through instead of a JSON 404`, async () => {
			const res = middleware(mcpRequest("/mcp", method));

			expect(res.status).not.toBe(404);
			// NextResponse.next(): Next continues to the rewrite table.
			expect(res.headers.get("x-middleware-next")).toBe("1");
			expect(res.headers.get("content-type") ?? "").not.toContain(
				"application/problem+json",
			);
			expect(eventNames()).not.toContain("agent:not-found");
		});
	}

	it("counts /mcp as an MCP agent-surface request", () => {
		middleware(mcpRequest("/mcp"));

		const call = reportServerEvent.mock.calls.find(
			(c) => c[1] === "agent:api-request",
		);
		expect(call?.[2]).toBe("/mcp");
		expect(call?.[3]).toMatchObject({ surface: "mcp" });
	});

	it("the sibling MCP paths also pass through", () => {
		for (const path of ["/api/mcp", "/mcp.json", "/.well-known/mcp"]) {
			reportServerEvent.mockClear();
			const res = middleware(mcpRequest(path, "GET"));
			expect(res.status, path).not.toBe(404);
			expect(eventNames(), path).not.toContain("agent:not-found");
		}
	});

	it("an unknown path still gets the structured 404 (the guard is not disabled)", () => {
		const res = middleware(mcpRequest("/mcp-nope"));

		expect(res.status).toBe(404);
		expect(eventNames()).toContain("agent:not-found");
	});
});
